import java.util.*;

public class Main {
    ListNode reverseList(ListNode head) {
        ListNode prev = null;                                                     // the already-reversed portion built so far (starts empty)
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;                                              // save the rest of the original list before overwriting curr.next
            curr.next = prev;                                                       // flip this node's pointer to point backward
            prev = curr;                                                            // curr becomes the new head of the reversed portion
            curr = next;                                                            // advance to the next unprocessed node
        }
        return prev;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.reverseList(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

